import pytest
from candidate import hex_key

class TestHexKey(unittest.TestCase):
    def test_hex_key_example_ab(self):
        self.assertEqual(hex_key("AB"), 1)

    def test_hex_key_example_1077e(self):
        self.assertEqual(hex_key("1077E"), 2)

    def test_hex_key_example_abed1a33(self):
        self.assertEqual(hex_key("ABED1A33"), 4)

    def test_hex_key_example_full_range(self):
        self.assertEqual(hex_key("123456789ABCDEF0"), 6)

    def test_hex_key_example_2020(self):
        self.assertEqual(hex_key("2020"), 2)

    def test_hex_key_empty_string(self):
        self.assertEqual(hex_key(""), 0)

    def test_hex_key_single_prime_digit_2(self):
        self.assertEqual(hex_key("2"), 1)

    def test_hex_key_single_prime_digit_3(self):
        self.assertEqual(hex_key("3"), 1)

    def test_hex_key_single_prime_digit_5(self):
        self.assertEqual(hex_key("5"), 1)

    def test_hex_key_single_prime_digit_7(self):
        self.assertEqual(hex_key("7"), 1)

    def test_hex_key_single_prime_digit_b(self):
        self.assertEqual(hex_key("B"), 1)

    def test_hex_key_single_prime_digit_d(self):
        self.assertEqual(hex_key("D"), 1)

    def test_hex_key_single_non_prime_digit_0(self):
        self.assertEqual(hex_key("0"), 0)

    def test_hex_key_single_non_prime_digit_1(self):
        self.assertEqual(hex_key("1"), 0)

    def test_hex_key_single_non_prime_digit_a(self):
        self.assertEqual(hex_key("A"), 0)

    def test_hex_key_single_non_prime_digit_c(self):
        self.assertEqual(hex_key("C"), 0)

    def test_hex_key_single_non_prime_digit_e(self):
        self.assertEqual(hex_key("E"), 0)

    def test_hex_key_single_non_prime_digit_f(self):
        self.assertEqual(hex_key("F"), 0)

    def test_hex_key_all_primes(self):
        self.assertEqual(hex_key("2357BD"), 6)

    def test_hex_key_no_primes(self):
        self.assertEqual(hex_key("014689ACEF"), 0)

    def test_hex_key_all_same_prime(self):
        self.assertEqual(hex_key("2222"), 4)

    def test_hex_key_all_same_non_prime(self):
        self.assertEqual(hex_key("AAAA"), 0)

    def test_hex_key_repeated_prime_b(self):
        self.assertEqual(hex_key("BBB"), 3)

    def test_hex_key_repeated_prime_d(self):
        self.assertEqual(hex_key("DDD"), 3)

    def test_hex_key_mixed_primes_and_non_primes(self):
        self.assertEqual(hex_key("0A2C4E6"), 1)

    def test_hex_key_long_string(self):
        self.assertEqual(hex_key("2" * 100), 100)

    def test_hex_key_long_string_no_primes(self):
        self.assertEqual(hex_key("0" * 100), 0)

    def test_hex_key_alternating_prime_non_prime(self):
        self.assertEqual(hex_key("20"), 1)

    def test_hex_key_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            hex_key(None)

    def test_hex_key_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            hex_key(1234)

    def test_hex_key_float_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            hex_key(3.14)

    def test_hex_key_list_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            hex_key(["A", "B"])

    def test_hex_key_tuple_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            hex_key(("A", "B"))

    def test_hex_key_bytes_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            hex_key(b"AB")

    def test_hex_key_prime_count_in_middle(self):
        self.assertEqual(hex_key("112233445566778899"), 4)

    def test_hex_key_all_b_digits(self):
        self.assertEqual(hex_key("BBBBBB"), 6)

    def test_hex_key_all_d_digits(self):
        self.assertEqual(hex_key("DDDDDD"), 6)

    def test_hex_key_abcdef_only(self):
        self.assertEqual(hex_key("ABCDEF"), 2)

    def test_hex_key_0123456789_only(self):
        self.assertEqual(hex_key("0123456789"), 4)

    def test_hex_key_single_zero(self):
        self.assertEqual(hex_key("0"), 0)

    def test_hex_key_single_nine(self):
        self.assertEqual(hex_key("9"), 0)

    def test_hex_key_four_digit_all_prime(self):
        self.assertEqual(hex_key("2357"), 4)

    def test_hex_key_four_digit_all_non_prime(self):
        self.assertEqual(hex_key("0146"), 0)

    def test_hex_key_result_is_integer(self):
        self.assertIsInstance(hex_key("AB"), int)

    def test_hex_key_result_non_negative(self):
        self.assertGreaterEqual(hex_key("AB"), 0)

    def test_hex_key_repeated_calls_same_result(self):
        self.assertEqual(hex_key("ABED1A33"), hex_key("ABED1A33"))

if __name__ == '__main__':
    unittest.main()
